#[allow(non_snake_case)]
fn __introspectGet_Point_label(instance: &dyn Introspect) -> Result<FieldValue, IntrospectError> {
    let s = instance.__introspectAsAny().downcast_ref::<Point>().ok_or("wrong instance type for field 'label'")?;
    Ok(FieldValue::Str(s.label.clone()))
}

#[allow(non_snake_case)]
fn __introspectGet_Point_active(instance: &dyn Introspect) -> Result<FieldValue, IntrospectError> {
    let s = instance.__introspectAsAny().downcast_ref::<Point>().ok_or("wrong instance type for field 'active'")?;
    Ok(FieldValue::Bool(s.active))
}

#[allow(non_snake_case)]
fn __introspectCall_Point_describe(instance: &dyn Introspect, args: &[FieldValue]) -> Result<FieldValue, IntrospectError> {
    let s = instance.__introspectAsAny().downcast_ref::<Point>().ok_or("wrong instance type for method 'describe'")?;
    if args.len() != 0 { return Err("wrong argument count for method 'describe'".into()); }
    let r = s.describe();
    Ok(FieldValue::Str(r.clone()))
}


fn main() -> Result<(), Box<dyn std::error::Error>> {
    let p: Point = Point { x: 1.5, y: 2.5, label: Rc::<str>::from("origin"), active: true };
    let info = p.introspect();
    println!("type: {}", info.typeName.clone());
    for f in info.fields.iter().cloned() {
        let v = f.get(&(p))?;
        println!("  {} = {:?}", f.name.clone(), v);
    }
    for m in info.methods.iter().cloned() {
        let r = m.request(&(p), &(vec![]))?;
        println!("  {}() = {:?}", m.name.clone(), r);
    }
    Ok(())
}

